"""Score a wallet A/B: median [range] wall time per transaction at each input count, from two CSVs (without the
change, with it) that have the columns n_inputs and wall_s, and the ratio of medians with an overlap check.
usage: python3 wallet_ab.py <without.csv>[:arm] <with.csv>[:arm] [n ...]   (default n: every count present in both)
A ":arm" suffix keeps only the rows whose "arm" column has that value (for a file that holds both arms)."""
import collections, csv, statistics, sys

if len(sys.argv) < 3:
    sys.exit(__doc__)

def load(spec):
    p, _, arm = spec.partition(":")
    d = collections.defaultdict(list)
    for r in csv.DictReader(open(p)):
        if arm and r.get("arm") != arm:
            continue
        d[int(r["n_inputs"])].append(float(r["wall_s"]))
    return d

a, b = load(sys.argv[1]), load(sys.argv[2])
ns = [int(x) for x in sys.argv[3:]] or sorted(set(a) & set(b))
for n in ns:
    ma, mb = statistics.median(a[n]), statistics.median(b[n])
    disjoint = max(b[n]) < min(a[n]) or min(b[n]) > max(a[n])
    print(f"n={n}: without {ma:.2f} s [{min(a[n]):.2f}-{max(a[n]):.2f}] ({len(a[n])} runs), "
          f"with {mb:.2f} s [{min(b[n]):.2f}-{max(b[n]):.2f}] ({len(b[n])} runs): "
          f"{mb / ma:.3f} ({(mb / ma - 1) * 100:+.0f}%, {'no overlap' if disjoint else 'overlap'})")
